import subprocess, collections

def git(*args):
    return subprocess.check_output(['git', *args])
head=git('rev-parse','HEAD').decode().strip()
prior,incoming=git('show','-s','--format=%P',head).decode().split()
base=git('merge-base',prior,incoming).decode().strip()
def tree(ref):
    return {row.split(b'\\t',1)[1].decode():row.split(b'\\t',1)[0] for row in git('ls-tree','-rz',ref).split(b'\\0') if row}
trees={ref:tree(ref) for ref in [head,prior,incoming,base]}
protected=[path for path in trees[incoming] if path.startswith(('MIPStarRE/','references/','blueprint/','docs/paper-gaps/')) or path=='MIPStarRE.lean']
print('head',head,'parents',prior,incoming,'merge-base',base)
print('Protected incoming paths:',len(protected),'mismatches:',[path for path in protected if trees[head].get(path)"'!=trees[incoming][path]])
incoming_only=[path for path in trees[incoming] if trees[incoming].get(path)!=trees[base].get(path) and trees[prior].get(path)==trees[base].get(path)]
print('"'Incoming-only changes:',len(incoming_only),'mismatches:',[path for path in incoming_only if trees[head].get(path)"'!=trees[incoming][path]])
print('"'Incoming paths absent from head:',sorted(set(trees[incoming])-set(trees[head])))
print('Delta vs incoming:',[path for path in sorted(set(trees[head])|set(trees[incoming])) if trees[head].get(path)"'!=trees[incoming].get(path)])
print('"'Persona identical to prior:',trees[head]['local/personas/main.md']==trees[prior]['local/personas/main.md'])
for path in ['local/protocols/EVOLUTION.md','results/telemetry/events.md']:
    texts={ref:git('show',f'{ref}:{path}').decode() for ref in [head,prior,incoming]}
    for ref in [prior,incoming]:
        missing=collections.Counter(texts[ref].splitlines())-collections.Counter(texts[head].splitlines())
        print(path,ref[:8],'missing line multiplicities:',dict(missing))
    if path.endswith('EVOLUTION.md'):
        def blocks(text):
            parts=text.split('\\n## ')
            return {part.splitlines()[0]:part.rstrip() for part in parts[1:]}
        merged=blocks(texts[head])
        for ref in [prior,incoming]:
            original=blocks(texts[ref])
            print('Evolution block preservation',ref[:8], all(merged.get(title)==body for title,body in original.items()))
        print('Incoming evolution is exact prefix:',texts[head].startswith(texts[incoming]))
    else:
        for ref in [prior,incoming]:
            remaining=iter(texts[head].splitlines())
            print('Events ordered subsequence',ref[:8],all(any(candidate==line for candidate in remaining) for line in texts[ref].splitlines()))
print('Worktree status:',git('status','--porcelain').decode() or 'clean')
